   pure module subroutine cfc_atomic_nuclear_eval(d_a, R_a, a1, fade_start, fade_width, max_deriv, &
                                           qn0_a, qn1_r_a, qn2_rr_a, qn3_rrr_a)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dr_a of the order-0 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn0_a(3)
      !> d/dr_a of the order-1 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn1_r_a(3, 3)
      !> d/dr_a of the order-2 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn2_rr_a(3, 3, 3)
      !> d/dr_a of the order-3 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn3_rrr_a(3, 3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a1 sigma_a)
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, e_a = w_a exp(a1 sigma_a)
      real(wp) :: e_a(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      if (sg_a > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_atomic_nuclear_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
               x0 = e_a(1)/(R_a*sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3)))))
               qn0_a(1) = qn0_a(1) + (-d_a(1)*x0)
               qn0_a(2) = qn0_a(2) + (-d_a(2)*x0)
               qn0_a(3) = qn0_a(3) + (-d_a(3)*x0)
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = &
                  fu*((a1*a1)*fj0 + 2.0_wp*a1*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               x0 = (d_a(1)*d_a(1))
               x1 = (d_a(2)*d_a(2))
               x2 = (d_a(3)*d_a(3))
               x3 = x0 + x1 + x2
               x4 = 1.0_wp/R_a
               x5 = e_a(1)*x4
               x6 = x5/sqrt(x3)
               x7 = e_a(2)/((R_a*R_a)*x3)
               x8 = 1.0_wp/(x3*sqrt(x3))
               x9 = x5*x8
               x10 = d_a(1)*d_a(2)
               x11 = -x10*x7 + x10*x9
               x12 = d_a(1)*d_a(3)
               x13 = -x12*x7 + x12*x9
               x14 = d_a(2)*d_a(3)
               x15 = -x14*x7 + x14*x9
               qn0_a(1) = qn0_a(1) + (-d_a(1)*x6)
               qn0_a(2) = qn0_a(2) + (-d_a(2)*x6)
               qn0_a(3) = qn0_a(3) + (-d_a(3)*x6)
               qn1_r_a(1, 1) = qn1_r_a(1, 1) + (e_a(1)*x0*x4*x8 - x0*x7 - x6)
               qn1_r_a(1, 2) = qn1_r_a(1, 2) + (x11)
               qn1_r_a(1, 3) = qn1_r_a(1, 3) + (x13)
               qn1_r_a(2, 1) = qn1_r_a(2, 1) + (x11)
               qn1_r_a(2, 2) = qn1_r_a(2, 2) + (e_a(1)*x1*x4*x8 - x1*x7 - x6)
               qn1_r_a(2, 3) = qn1_r_a(2, 3) + (x15)
               qn1_r_a(3, 1) = qn1_r_a(3, 1) + (x13)
               qn1_r_a(3, 2) = qn1_r_a(3, 2) + (x15)
               qn1_r_a(3, 3) = qn1_r_a(3, 3) + (e_a(1)*x2*x4*x8 - x2*x7 - x6)
            end block
         case (2)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
               real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, t_qn2_rr_a_010
               real(wp) :: t_qn2_rr_a_011, t_qn2_rr_a_012, t_qn2_rr_a_020, t_qn2_rr_a_021
               real(wp) :: t_qn2_rr_a_022, t_qn2_rr_a_120, t_qn2_rr_a_121, t_qn2_rr_a_122

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fp3 = -1680.0_wp*ft - 210.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               fj2 = (a1*a1)
               fj3 = fp2*fsp2
               fj4 = fp1*fs
               fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = fu*(2.0_wp*a1*fj1 + fj0*fj2 + fj5)
               e_a(3) = &
                  fu*((a1*a1*a1)*fj0 + 3.0_wp*a1*fj5 + (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + &
                  60.0_wp*fj4 + 60.0_wp*fp0 + fp3*fsp3) + 3.0_wp*fj1*fj2)
               x0 = (d_a(1)*d_a(1))
               x1 = (d_a(2)*d_a(2))
               x2 = (d_a(3)*d_a(3))
               x3 = x0 + x1 + x2
               x4 = 1.0_wp/R_a
               x5 = e_a(1)*x4
               x6 = x5/sqrt(x3)
               x7 = 1.0_wp/(R_a*R_a)
               x8 = e_a(2)*x7/x3
               x9 = 1.0_wp/(x3*sqrt(x3))
               x10 = x5*x9
               x11 = d_a(2)*x10
               x12 = d_a(2)*x8
               x13 = d_a(1)*x11 - d_a(1)*x12
               x14 = d_a(3)*x8
               x15 = d_a(1)*d_a(3)*x10 - d_a(1)*x14
               x16 = d_a(3)*x11 - d_a(3)*x12
               x17 = d_a(1)*x8
               x18 = (d_a(1)*d_a(1)*d_a(1))
               x19 = e_a(3)*x9/(R_a*R_a*R_a)
               x20 = 1.0_wp/(x3*x3)
               x21 = x5/(x3*x3*sqrt(x3))
               x22 = x0*x19
               x23 = 3.0_wp*x0
               x24 = -d_a(2)*e_a(1)*x4*x9 + x12
