            qn3_rrr_a(1, 3, 1, 2) = qn3_rrr_a(1, 3, 1, 2) + t_qn3_rrr_a_0021
            qn3_rrr_a(3, 1, 1, 2) = qn3_rrr_a(3, 1, 1, 2) + t_qn3_rrr_a_0021
            t_qn3_rrr_a_0022 = x78
            qn3_rrr_a(1, 1, 3, 3) = qn3_rrr_a(1, 1, 3, 3) + t_qn3_rrr_a_0022
            qn3_rrr_a(1, 3, 1, 3) = qn3_rrr_a(1, 3, 1, 3) + t_qn3_rrr_a_0022
            qn3_rrr_a(3, 1, 1, 3) = qn3_rrr_a(3, 1, 1, 3) + t_qn3_rrr_a_0022
            t_qn3_rrr_a_0110 = x74
            qn3_rrr_a(1, 2, 2, 1) = qn3_rrr_a(1, 2, 2, 1) + t_qn3_rrr_a_0110
            qn3_rrr_a(2, 1, 2, 1) = qn3_rrr_a(2, 1, 2, 1) + t_qn3_rrr_a_0110
            qn3_rrr_a(2, 2, 1, 1) = qn3_rrr_a(2, 2, 1, 1) + t_qn3_rrr_a_0110
            t_qn3_rrr_a_0111 = x80
