            qn3_rrr_a(2, 1, 2, 2) = qn3_rrr_a(2, 1, 2, 2) + t_qn3_rrr_a_0111
            qn3_rrr_a(2, 2, 1, 2) = qn3_rrr_a(2, 2, 1, 2) + t_qn3_rrr_a_0111
            t_qn3_rrr_a_0112 = x81
