            qn3_rrr_a(1, 3, 2, 1) = qn3_rrr_a(1, 3, 2, 1) + t_qn3_rrr_a_0120
            qn3_rrr_a(2, 1, 3, 1) = qn3_rrr_a(2, 1, 3, 1) + t_qn3_rrr_a_0120
            qn3_rrr_a(2, 3, 1, 1) = qn3_rrr_a(2, 3, 1, 1) + t_qn3_rrr_a_0120
            qn3_rrr_a(3, 1, 2, 1) = qn3_rrr_a(3, 1, 2, 1) + t_qn3_rrr_a_0120
            qn3_rrr_a(3, 2, 1, 1) = qn3_rrr_a(3, 2, 1, 1) + t_qn3_rrr_a_0120
            t_qn3_rrr_a_0121 = x81
            qn3_rrr_a(1, 2, 3, 2) = qn3_rrr_a(1, 2, 3, 2) + t_qn3_rrr_a_0121
            qn3_rrr_a(1, 3, 2, 2) = qn3_rrr_a(1, 3, 2, 2) + t_qn3_rrr_a_0121
            qn3_rrr_a(2, 1, 3, 2) = qn3_rrr_a(2, 1, 3, 2) + t_qn3_rrr_a_0121
            qn3_rrr_a(2, 3, 1, 2) = qn3_rrr_a(2, 3, 1, 2) + t_qn3_rrr_a_0121
            qn3_rrr_a(3, 1, 2, 2) = qn3_rrr_a(3, 1, 2, 2) + t_qn3_rrr_a_0121
            qn3_rrr_a(3, 2, 1, 2) = qn3_rrr_a(3, 2, 1, 2) + t_qn3_rrr_a_0121
            t_qn3_rrr_a_0122 = x82
            qn3_rrr_a(1, 2, 3, 3) = qn3_rrr_a(1, 2, 3, 3) + t_qn3_rrr_a_0122
            qn3_rrr_a(1, 3, 2, 3) = qn3_rrr_a(1, 3, 2, 3) + t_qn3_rrr_a_0122
            qn3_rrr_a(2, 1, 3, 3) = qn3_rrr_a(2, 1, 3, 3) + t_qn3_rrr_a_0122
            qn3_rrr_a(2, 3, 1, 3) = qn3_rrr_a(2, 3, 1, 3) + t_qn3_rrr_a_0122
            qn3_rrr_a(3, 1, 2, 3) = qn3_rrr_a(3, 1, 2, 3) + t_qn3_rrr_a_0122
            qn3_rrr_a(3, 2, 1, 3) = qn3_rrr_a(3, 2, 1, 3) + t_qn3_rrr_a_0122
            t_qn3_rrr_a_0220 = x78
            qn3_rrr_a(1, 3, 3, 1) = qn3_rrr_a(1, 3, 3, 1) + t_qn3_rrr_a_0220
            qn3_rrr_a(3, 1, 3, 1) = qn3_rrr_a(3, 1, 3, 1) + t_qn3_rrr_a_0220
            qn3_rrr_a(3, 3, 1, 1) = qn3_rrr_a(3, 3, 1, 1) + t_qn3_rrr_a_0220
            t_qn3_rrr_a_0221 = x82
            qn3_rrr_a(1, 3, 3, 2) = qn3_rrr_a(1, 3, 3, 2) + t_qn3_rrr_a_0221
            qn3_rrr_a(3, 1, 3, 2) = qn3_rrr_a(3, 1, 3, 2) + t_qn3_rrr_a_0221
            qn3_rrr_a(3, 3, 1, 2) = qn3_rrr_a(3, 3, 1, 2) + t_qn3_rrr_a_0221
            t_qn3_rrr_a_0222 = x83
            qn3_rrr_a(1, 3, 3, 3) = qn3_rrr_a(1, 3, 3, 3) + t_qn3_rrr_a_0222
            qn3_rrr_a(3, 1, 3, 3) = qn3_rrr_a(3, 1, 3, 3) + t_qn3_rrr_a_0222
            qn3_rrr_a(3, 3, 1, 3) = qn3_rrr_a(3, 3, 1, 3) + t_qn3_rrr_a_0222
            qn3_rrr_a(2, 2, 2, 1) = qn3_rrr_a(2, 2, 2, 1) + (x80)
            qn3_rrr_a(2, 2, 2, 2) = &
               qn3_rrr_a(2, 2, 2, 2) + (15.0_wp*a1*x5*x56*x6*x84 + 18.0_wp*x1*x10*x11*x29*x6 - &
               18.0_wp*x1*x24 + 6.0_wp*x23*x26*x27*x6*x84 - 6.0_wp*x38 - 15.0_wp*x57*x84 - x58 - &
               x68*x84)
            qn3_rrr_a(2, 2, 2, 3) = qn3_rrr_a(2, 2, 2, 3) + (x87)
            t_qn3_rrr_a_1120 = x81
            qn3_rrr_a(2, 2, 3, 1) = qn3_rrr_a(2, 2, 3, 1) + t_qn3_rrr_a_1120
            qn3_rrr_a(2, 3, 2, 1) = qn3_rrr_a(2, 3, 2, 1) + t_qn3_rrr_a_1120
            qn3_rrr_a(3, 2, 2, 1) = qn3_rrr_a(3, 2, 2, 1) + t_qn3_rrr_a_1120
            t_qn3_rrr_a_1121 = x87
            qn3_rrr_a(2, 2, 3, 2) = qn3_rrr_a(2, 2, 3, 2) + t_qn3_rrr_a_1121
            qn3_rrr_a(2, 3, 2, 2) = qn3_rrr_a(2, 3, 2, 2) + t_qn3_rrr_a_1121
            qn3_rrr_a(3, 2, 2, 2) = qn3_rrr_a(3, 2, 2, 2) + t_qn3_rrr_a_1121
            t_qn3_rrr_a_1122 = x89
            qn3_rrr_a(2, 2, 3, 3) = qn3_rrr_a(2, 2, 3, 3) + t_qn3_rrr_a_1122
            qn3_rrr_a(2, 3, 2, 3) = qn3_rrr_a(2, 3, 2, 3) + t_qn3_rrr_a_1122
            qn3_rrr_a(3, 2, 2, 3) = qn3_rrr_a(3, 2, 2, 3) + t_qn3_rrr_a_1122
            t_qn3_rrr_a_1220 = x82
            qn3_rrr_a(2, 3, 3, 1) = qn3_rrr_a(2, 3, 3, 1) + t_qn3_rrr_a_1220
            qn3_rrr_a(3, 2, 3, 1) = qn3_rrr_a(3, 2, 3, 1) + t_qn3_rrr_a_1220
            qn3_rrr_a(3, 3, 2, 1) = qn3_rrr_a(3, 3, 2, 1) + t_qn3_rrr_a_1220
            t_qn3_rrr_a_1221 = x89
            qn3_rrr_a(2, 3, 3, 2) = qn3_rrr_a(2, 3, 3, 2) + t_qn3_rrr_a_1221
            qn3_rrr_a(3, 2, 3, 2) = qn3_rrr_a(3, 2, 3, 2) + t_qn3_rrr_a_1221
            qn3_rrr_a(3, 3, 2, 2) = qn3_rrr_a(3, 3, 2, 2) + t_qn3_rrr_a_1221
            t_qn3_rrr_a_1222 = x91
            qn3_rrr_a(2, 3, 3, 3) = qn3_rrr_a(2, 3, 3, 3) + t_qn3_rrr_a_1222
            qn3_rrr_a(3, 2, 3, 3) = qn3_rrr_a(3, 2, 3, 3) + t_qn3_rrr_a_1222
            qn3_rrr_a(3, 3, 2, 3) = qn3_rrr_a(3, 3, 2, 3) + t_qn3_rrr_a_1222
            qn3_rrr_a(3, 3, 3, 1) = qn3_rrr_a(3, 3, 3, 1) + (x83)
            qn3_rrr_a(3, 3, 3, 2) = qn3_rrr_a(3, 3, 3, 2) + (x91)
            qn3_rrr_a(3, 3, 3, 3) = &
               qn3_rrr_a(3, 3, 3, 3) + (15.0_wp*a1*x5*x56*x6*x92 + 18.0_wp*x10*x11*x2*x29*x6 - &
               18.0_wp*x2*x24 + 6.0_wp*x23*x26*x27*x6*x92 - 6.0_wp*x47 - 15.0_wp*x57*x92 - x58 - &
               x68*x92)
         end block
      end select

   end subroutine cfc_atomic_nuclear_eval

   pure module subroutine cfc_pair_nuclear_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                         max_deriv, qn0_a, qn0_b, qn1_r_a, qn1_r_b, qn2_rr_a, &
                                         qn2_rr_b, qn3_rrr_a, qn3_rrr_b)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> d/dr_a of the order-0 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn0_a(3)
      !> d/dr_b of the order-0 spatial derivative; trailing index is the nuclear component of atom b
      real(wp), intent(inout) :: qn0_b(3)
      !> d/dr_a of the order-1 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn1_r_a(3, 3)
      !> d/dr_b of the order-1 spatial derivative; trailing index is the nuclear component of atom b
      real(wp), intent(inout) :: qn1_r_b(3, 3)
      !> d/dr_a of the order-2 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn2_rr_a(3, 3, 3)
      !> d/dr_b of the order-2 spatial derivative; trailing index is the nuclear component of atom b
      real(wp), intent(inout) :: qn2_rr_b(3, 3, 3)
      !> d/dr_a of the order-3 spatial derivative; trailing index is the nuclear component of atom a
      real(wp), intent(inout) :: qn3_rrr_a(3, 3, 3, 3)
      !> d/dr_b of the order-3 spatial derivative; trailing index is the nuclear component of atom b
      real(wp), intent(inout) :: qn3_rrr_b(3, 3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_pair_nuclear_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end .or. sg_b >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               g_b(0) = fj0
               g_b(1) = a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               x0 = 1.0_wp/R_a
               x1 = 1.0_wp/R_b
               x2 = -x0*x1*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
               x3 = (x2*x2*x2)
               x4 = c_par*(x2*x2*x2*x2)
               x5 = g_a(1)*x0*x4/sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
               x6 = g_b(0)*x5
               x7 = g_b(1)*x1*x4/sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
               x8 = g_a(0)*x7
               qn0_a(1) = qn0_a(1) + (4.0_wp*c_par*d_b(1)*g_a(0)*g_b(0)*x0*x1*x3 - d_a(1)*g_b(0)*x5)
               qn0_a(2) = qn0_a(2) + (4.0_wp*c_par*d_b(2)*g_a(0)*g_b(0)*x0*x1*x3 - d_a(2)*x6)
               qn0_a(3) = qn0_a(3) + (4.0_wp*c_par*d_b(3)*g_a(0)*g_b(0)*x0*x1*x3 - d_a(3)*x6)
               qn0_b(1) = qn0_b(1) + (4.0_wp*c_par*d_a(1)*g_a(0)*g_b(0)*x0*x1*x3 - d_b(1)*g_a(0)*x7)
               qn0_b(2) = qn0_b(2) + (4.0_wp*c_par*d_a(2)*g_a(0)*g_b(0)*x0*x1*x3 - d_b(2)*x8)
               qn0_b(3) = qn0_b(3) + (4.0_wp*c_par*d_a(3)*g_a(0)*g_b(0)*x0*x1*x3 - d_b(3)*x8)
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
               real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
               real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
               real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
               real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + fj1)
               g_a(2) = &
                  fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_b(0) = fj0
               g_b(1) = a2*fj0 + fj1
               g_b(2) = &
                  (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
                  fp2*fsp2)
               x0 = 1.0_wp/R_a
               x1 = 1.0_wp/R_b
               x2 = d_a(1)*d_b(1)
               x3 = d_a(2)*d_b(2)
               x4 = d_a(3)*d_b(3)
               x5 = x0*x1
               x6 = -x5*(x2 + x3 + x4) + 1.0_wp
               x7 = (x6*x6*x6)
               x8 = (d_a(1)*d_a(1))
